import type {ConfigField} from './configurationTypes';

type Section=ConfigField['section'];
const field=(key:string,label:string,kind:ConfigField['kind'],section:Section,help:string,extra:Partial<ConfigField>={}):ConfigField=>({key,label,kind,section,help,...extra});
const t=(k:string,l:string,s:Section,h:string)=>field(k,l,'text',s,h);
const s=(k:string,l:string,o:string[],section:Section,h:string,extra:Partial<ConfigField>={})=>field(k,l,'select',section,h,{options:o,...extra});
const b=(k:string,l:string,section:Section,h:string)=>field(k,l,'boolean',section,h);
const n=(k:string,l:string,section:Section,h:string,unit?:string,extra:Partial<ConfigField>={})=>field(k,l,'number',section,h,{min:0,unit,...extra});
const r=(k:string,l:string,services:string[],section:Section,h:string)=>field(k,l,'resource',section,h,{resourceServices:services});
const kv=(k:string,l:string,section:Section,h:string)=>field(k,l,'key-value',section,h);
const doc=(k:string,l:string,section:Section,h:string,type:'json'|'yaml'|'resource-policy'='json')=>field(k,l,type==='yaml'?'yaml':'json',section,h,{documentType:type});
const table=(k:string,l:string,section:Section,h:string,rows:ConfigField[])=>field(k,l,'table',section,h,{itemFields:rows});
const at=(f:ConfigField,when:NonNullable<ConfigField['when']>)=>({...f,when});
const source=(title:string,url:string)=>({title,url,verified:'2026-11-01'});
function profile(title:string,url:string,objectives:string[],fields:ConfigField[]):ConfigField[]{
 const attach=(f:ConfigField):ConfigField=>({...f,source:f.source??source(title,url),objectives:f.objectives??objectives,tier:f.tier??'core',...(f.itemFields?{itemFields:f.itemFields.map(attach)}:{})});
 return fields.map(attach);
}
