// Conditional top-level controls retain their data when hidden; the validator
// still checks incompatible combinations instead of silently deleting values.
const conditional:Record<string,Record<string,NonNullable<ConfigField['when']>>>={
  'elastic-beanstalk':{trafficSplitPercent:{field:'deploymentPolicy',values:['traffic-splitting']}},
  ecr:{kmsKey:{field:'encryption',values:['kms']}},
  ecs:{assignPublicIp:{field:'networkMode',values:['awsvpc']},securityRules:{field:'networkMode',values:['awsvpc']},deploymentCircuitBreaker:{field:'deploymentController',values:['ecs']},minimumHealthyPercent:{field:'deploymentController',values:['ecs']},maximumPercent:{field:'deploymentController',values:['ecs']},minTasks:{field:'autoScaling',values:[true]},maxTasks:{field:'autoScaling',values:[true]}},
  aurora:{minCapacityAcu:{field:'capacity',values:['serverless-v2']},maxCapacityAcu:{field:'capacity',values:['serverless-v2']}},
  elasticache:{clusterMode:{field:'deployment',values:['node-based']},shards:{field:'deployment',values:['node-based']},replicasPerShard:{field:'deployment',values:['node-based']},multiAz:{field:'deployment',values:['node-based']},automaticFailover:{field:'deployment',values:['node-based']}},
  ebs:{iops:{field:'volumeType',values:['gp3','io2','io1']},throughputMib:{field:'volumeType',values:['gp3']},multiAttach:{field:'volumeType',values:['io2','io1']}},
  efs:{provisionedThroughputMib:{field:'throughputMode',values:['provisioned']}},
  elb:{routingRules:{field:'loadBalancerType',values:['application']}},
  route53:{associatedVpc:{field:'zoneType',values:['private']}},
  privatelink:{privateDns:{field:'endpointType',values:['interface']},endpointPolicy:{field:'endpointType',values:['interface']}},
};
for(const [id,rules] of Object.entries(conditional))configurationPlatformFields[id]=configurationPlatformFields[id].map(f=>rules[f.key]?{...f,when:rules[f.key]}:f);

// Prefer relevant feature documentation to attaching one overview to every field.
const featureSources:Record<string,{match:(f:ConfigField)=>boolean;title:string;url:string}[]>={
 ec2:[
  {match:f=>f.key==='instanceProfile',title:'EC2 instance profiles and temporary role credentials',url:'https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/iam-roles-for-amazon-ec2.html'},
  {match:f=>f.section==='networking',title:'VPC security-group rules',url:'https://docs.aws.amazon.com/vpc/latest/userguide/vpc-security-groups.html'},
  {match:f=>['autoScaling','minInstances','desiredInstances','maxInstances'].includes(f.key),title:'Auto Scaling desired/minimum/maximum capacity',url:'https://docs.aws.amazon.com/autoscaling/ec2/userguide/asg-capacity-limits.html'},
 ],
 'elastic-beanstalk':[{match:f=>['configuration','networking','monitoring','permissions'].includes(f.section),title:'Elastic Beanstalk environment management',url:'https://docs.aws.amazon.com/elasticbeanstalk/latest/dg/using-features.managing.html'}],
 ecr:[{match:f=>f.key==='lifecyclePolicy',title:'ECR lifecycle policies',url:'https://docs.aws.amazon.com/AmazonECR/latest/userguide/LifecyclePolicies.html'},{match:f=>['scanType','scanOnPush'].includes(f.key),title:'ECR image scanning',url:'https://docs.aws.amazon.com/AmazonECR/latest/userguide/image-scanning.html'}],
 ecs:[{match:f=>f.section==='permissions'||f.key==='secrets',title:'ECS task, execution and other IAM roles',url:'https://docs.aws.amazon.com/AmazonECS/latest/developerguide/security-iam-roles.html'},{match:f=>['deploymentController','minimumHealthyPercent','maximumPercent','deploymentCircuitBreaker','rollbackOnFailure','desiredCount'].includes(f.key),title:'ECS rolling deployments',url:'https://docs.aws.amazon.com/AmazonECS/latest/developerguide/deployment-type-ecs.html'}],
 rds:[{match:f=>['authentication','clientRole'].includes(f.key),title:'RDS IAM database authentication',url:'https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/UsingWithRDS.IAMDBAuth.html'},{match:f=>f.section==='networking',title:'RDS network access and security groups',url:'https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/Overview.RDSSecurityGroups.html'},{match:f=>f.key==='backupRetentionDays',title:'RDS automated backups',url:'https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_WorkingWithAutomatedBackups.html'}],
 elasticache:[{match:f=>f.key==='transitEncryption',title:'ElastiCache TLS constraints',url:'https://docs.aws.amazon.com/AmazonElastiCache/latest/dg/in-transit-encryption.html'}],
 efs:[{match:f=>f.section==='permissions',title:'EFS IAM client authorization and resource policies',url:'https://docs.aws.amazon.com/efs/latest/ug/iam-access-control-nfs-efs.html'}],
 cloudfront:[{match:f=>f.key==='originAccessPolicy',title:'CloudFront origin access control for S3',url:'https://docs.aws.amazon.com/AmazonCloudFront/latest/DeveloperGuide/private-content-restricting-access-to-s3.html'}],
 route53:[{match:f=>f.key==='healthChecks',title:'Route 53 health-check types',url:'https://docs.aws.amazon.com/Route53/latest/DeveloperGuide/dns-failover.html'}],
};
for(const [id,rules]of Object.entries(featureSources))configurationPlatformFields[id]=configurationPlatformFields[id].map(f=>{
 const selected=rules.find(rule=>rule.match(f));if(!selected)return f;
 const annotate=(item:ConfigField):ConfigField=>({...item,source:source(selected.title,selected.url),...(item.itemFields?{itemFields:item.itemFields.map(annotate)}:{})});
 return annotate(f);
});
